2	 * browserSearch.js — Shared search engine for Meridian
3	 *
4	 * Exports two groups:
5	 *   A) Index management  — initTabIndex(), rebuildIndex()  (called from background.js)
6	 *   B) Search functions  — search(query), getPreviousTab() (called from popup.js / meridian.js)
7	 */
8	
9	// ---------------------------------------------------------------------------
10	// Internal helpers
11	// ---------------------------------------------------------------------------
12	
13	/**
14	 * Extract the root domain from a URL string.
15	 * Returns "" for non-http(s) URLs or on parse failure.
16	 */
17	function extractDomain(url) {
18	  if (!url) return "";
19	  try {
20	    const { hostname } = new URL(url);
21	    // Strip leading "www."
22	    return hostname.replace(/^www\./, "");
23	  } catch (_) {
24	    return "";
25	  }
26	}
27	
28	/**
29	 * Build a Google favicon URL for a given domain or full URL.
30	 */
31	function faviconUrl(domain) {
32	  if (!domain) return "";
33	  return `https://www.google.com/s2/favicons?domain=${encodeURIComponent(domain)}&sz=16`;
34	}
35	
36	/**
37	 * Fuzzy score — returns a value 0–1.
38	 *
39	 * Rules (case-insensitive):
40	 *   1. Exact substring match                         → 1.0
41	 *   2. All query chars appear in order (subsequence) → 0.3–0.7, scaled by compactness
42	 *   3. No match                                      → 0
43	 *
44	 * "Compactness" = how short the matched span is relative to the text length.
45	 * A perfectly compact match (every char adjacent) scores 0.7;
46	 * a very spread-out match floors at 0.3.
47	 */
48	function fuzzyScore(query, text) {
49	  if (!query || !text) return 0;
50	
51	  const q = query.toLowerCase();
52	  const t = text.toLowerCase();
53	
54	  // 1. Exact substring
55	  if (t.includes(q)) return 1.0;
56	
57	  // 2. Subsequence match
58	  let qi = 0;
59	  let firstMatch = -1;
60	  let lastMatch = -1;
61	
62	  for (let ti = 0; ti < t.length && qi < q.length; ti++) {
63	    if (t[ti] === q[qi]) {
64	      if (firstMatch === -1) firstMatch = ti;
65	      lastMatch = ti;
66	      qi++;
67	    }
68	  }
69	
70	  if (qi < q.length) return 0; // not all chars found
71	
72	  const span = lastMatch - firstMatch + 1;
73	  // Compactness ratio: ideal span == q.length, worst == t.length
74	  const compactness = q.length / span;
75	  // Map compactness [0,1] → score [0.3, 0.7]
76	  return 0.3 + compactness * 0.4;
77	}
