27	export function getRootDomain(url) {
28	  try {
29	    const u = new URL(url);
30	    if (SYSTEM_PROTOCOLS.includes(u.protocol)) return null;
31	    const parts = u.hostname.split(".");
32	    return parts.length >= 2 ? parts.slice(-2).join(".") : u.hostname;
33	  } catch {
34	    return null;
35	  }
36	}
