38	export function domainToWorkspaceName(domain) {
39	  if (KNOWN_NAMES[domain]) return KNOWN_NAMES[domain];
40	  const base = domain.split(".")[0];
41	  return base
42	    .split("-")
43	    .map((w) => w.charAt(0).toUpperCase() + w.slice(1))
44	    .join(" ");
45	}
