47	export function clusterTabsByDomain(tabs) {
48	  const byDomain = new Map();
49	  for (const tab of tabs) {
50	    const domain = getRootDomain(tab.url || tab.pendingUrl || "");
51	    const name = domain ? domainToWorkspaceName(domain) : "Unsorted";
52	    if (!byDomain.has(name)) byDomain.set(name, []);
53	    byDomain.get(name).push(tab);
54	  }
55	
56	  const clusters = new Map();
57	  const unsorted = [];
58	  for (const [name, clusterTabs] of byDomain) {
59	    if (name !== "Unsorted" && clusterTabs.length >= 2) {
60	      clusters.set(name, clusterTabs);
61	    } else {
62	      unsorted.push(...clusterTabs);
63	    }
