1	import {
2	  assignTab,
3	  unassignTab,
4	  createWorkspace,
5	} from "../utils/workspaceManager.js";
6	
7	const hasNativeGroups = typeof chrome.tabGroups !== "undefined";
8	
9	let menuEl = null;
10	
11	function getMenu() {
12	  if (menuEl) return menuEl;
13	  menuEl = document.createElement("div");
14	  menuEl.className = "context-menu hidden";
15	  menuEl.setAttribute("role", "menu");
16	  document.body.appendChild(menuEl);
17	  document.addEventListener("mousedown", (e) => {
18	    if (!menuEl.contains(e.target)) hide();
19	  });
20	  document.addEventListener("keydown", (e) => {
21	    if (e.key === "Escape") hide();
22	  });
23	  return menuEl;
24	}
25	
26	export function hide() {
27	  getMenu().classList.add("hidden");
28	}
29	
30	function item(label, onClick) {
31	  const btn = document.createElement("button");
32	  btn.className = "context-menu-item";
33	  btn.setAttribute("role", "menuitem");
34	  btn.textContent = label;
35	  btn.addEventListener("click", (e) => {
36	    e.stopPropagation();
37	    hide();
38	    onClick();
39	  });
40	  return btn;
41	}
42	
43	function separator() {
44	  const el = document.createElement("div");
45	  el.className = "context-menu-separator";
46	  return el;
47	}
48	
49	export async function show(tab, x, y) {
50	  const menu = getMenu();
51	  menu.innerHTML = "";
52	
53	  const [chromeGroups, wsData] = await Promise.all([
54	    hasNativeGroups ? chrome.tabGroups.query({}) : Promise.resolve([]),
55	    (await import("../utils/workspaceManager.js")).getWorkspaceData(),
56	  ]);
57	
58	  const inChromeGroup = hasNativeGroups && tab.groupId !== -1;
59	  const wsId = wsData.assignments[String(tab.id)];
60	  const customWorkspaces = wsData.workspaces.filter((w) => w.id !== "unsorted");
61	
62	  // Move to new group
63	  menu.appendChild(
64	    item("Move to new group", async () => {
65	      const name = prompt("New group name:");
66	      if (!name?.trim()) return;
67	      if (hasNativeGroups) {
68	        if (inChromeGroup) await chrome.tabs.ungroup([tab.id]).catch(() => {});
69	        const groupId = await chrome.tabs.group({ tabIds: [tab.id] });
70	        await chrome.tabGroups.update(groupId, { title: name.trim() });
71	      } else {
72	        const ws = await createWorkspace(name.trim());
73	        await unassignTab(tab.id);
74	        await assignTab(tab.id, ws.id);
75	      }
76	    }),
77	  );
78	
79	  // Remove from group (if in one)
80	  if (inChromeGroup || wsId) {
81	    menu.appendChild(
82	      item("Remove from group", async () => {
83	        if (hasNativeGroups && inChromeGroup)
84	          await chrome.tabs.ungroup([tab.id]).catch(() => {});
85	        await unassignTab(tab.id);
86	      }),
87	    );
88	  }
89	
90	  // Move to existing Chrome groups
91	  const otherChromeGroups = chromeGroups.filter((g) => g.id !== tab.groupId);
92	  if (otherChromeGroups.length > 0) {
93	    menu.appendChild(separator());
94	    for (const g of otherChromeGroups) {
95	      const name = g.title?.trim() || g.color || "Group";
96	      menu.appendChild(
97	        item(`Move to "${name}"`, async () => {
98	          await chrome.tabs.group({ tabIds: [tab.id], groupId: g.id });
99	          await unassignTab(tab.id);
100	        }),
101	      );
102	    }
103	  }
104	
105	  // Move to existing Meridian workspaces
106	  const otherWorkspaces = customWorkspaces.filter((w) => w.id !== wsId);
107	  if (otherWorkspaces.length > 0) {
108	    menu.appendChild(separator());
109	    for (const ws of otherWorkspaces) {
110	      menu.appendChild(
111	        item(`Move to "${ws.name}"`, async () => {
112	          if (hasNativeGroups && inChromeGroup)
113	            await chrome.tabs.ungroup([tab.id]).catch(() => {});
114	          await assignTab(tab.id, ws.id);
115	        }),
116	      );
117	    }
118	  }
119	
120	  // Position
121	  menu.style.left = `${x}px`;
122	  menu.style.top = `${y}px`;
123	  menu.classList.remove("hidden");
124	
125	  // Nudge back on-screen if clipped
126	  requestAnimationFrame(() => {
127	    const r = menu.getBoundingClientRect();
128	    if (r.right > window.innerWidth) menu.style.left = `${x - r.width}px`;
129	    if (r.bottom > window.innerHeight) menu.style.top = `${y - r.height}px`;
130	  });
131	}
