// Custom background images can be large (multi-MB). They live in
// chrome.storage.local, which honors the `unlimitedStorage` permission —
// unlike localStorage, which is hard-capped at ~5MB per origin.
export const CUSTOM_BG_KEY = "meridian_bg_custom";

export async function getCustomBackground() {
  const data = await chrome.storage.local.get(CUSTOM_BG_KEY);
  if (data[CUSTOM_BG_KEY] != null) return data[CUSTOM_BG_KEY];
  // Legacy fallback: images uploaded before the storage move lived in
  // localStorage. Read (but don't rewrite) so existing backgrounds survive.
  return localStorage.getItem(CUSTOM_BG_KEY);
}

export async function setCustomBackground(dataUrl) {
  await chrome.storage.local.set({ [CUSTOM_BG_KEY]: dataUrl });
  // Clear any stale legacy copy so the two backends can't diverge.
  try {
    localStorage.removeItem(CUSTOM_BG_KEY);
  } catch {
    /* ignore */
  }
}

